const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikkelit</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Saksan artikkeli ei ole johdettavissa suomen kielestä, koska suomessa ei ole kieliopillista sukua. Siksi substantiivit kannattaa opetella aina yhdessä artikkelin kanssa.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Esimerkkejä artikkeleista</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — pöytä</div>\n      <div class=\"kurss-example\">die Tür — ovi</div>\n      <div class=\"kurss-example\">das Messer — veitsi</div>\n      <div class=\"kurss-example\">das Mädchen — tyttö</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Usein DER</h4>\n    <p class=\"artikuli-explain\">DER on usein miespuolisilla henkilöillä, viikonpäivillä, kuukausilla, vuodenajoilla ja joillakin sanoilla, joilla on tietty pääte.</p>\n\n    <h5 class=\"artikuli-subtitle\">Säännöt</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → usein DER, esimerkiksi: der Computer, der Lehrer <span class=\"artikuli-note\">mutta ei aina</span></div>\n      <div class=\"kurss-example\">-ling → usein DER, esimerkiksi: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → usein DER, esimerkiksi: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">miespuoliset henkilöt → der Mann, der Vater</div>\n      <div class=\"kurss-example\">ammatit → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">automerkit → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">viikonpäivät → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">kuukaudet → der August, der Dezember</div>\n      <div class=\"kurss-example\">vuodenajat → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esimerkit</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mies</div>\n      <div class=\"kurss-example\">der Vater — isä</div>\n      <div class=\"kurss-example\">der Montag — maanantai</div>\n      <div class=\"kurss-example\">der August — elokuu</div>\n      <div class=\"kurss-example\">der Sommer — kesä</div>\n      <div class=\"kurss-example\">der Lehrer — opettaja</div>\n      <div class=\"kurss-example\">der Computer — tietokone</div>\n      <div class=\"kurss-example\">der Schmetterling — perhonen</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Usein DIE</h4>\n    <p class=\"artikuli-explain\">DIE on usein naispuolisilla henkilöillä, monikossa ja sanoilla, joiden pääte on -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Säännöt</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">naispuoliset henkilöt → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">moottoripyörämerkit → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">monikko → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">monikko lähes aina → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esimerkit</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — nainen</div>\n      <div class=\"kurss-example\">die Mutter — äiti</div>\n      <div class=\"kurss-example\">die Wohnung — asunto</div>\n      <div class=\"kurss-example\">die Rechnung — lasku</div>\n      <div class=\"kurss-example\">die Freiheit — vapaus</div>\n      <div class=\"kurss-example\">die Möglichkeit — mahdollisuus</div>\n      <div class=\"kurss-example\">die Mannschaft — joukkue</div>\n      <div class=\"kurss-example\">die Nation — kansakunta</div>\n      <div class=\"kurss-example\">die Universität — yliopisto</div>\n      <div class=\"kurss-example\">die Polizei — poliisi</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Usein DAS</h4>\n    <p class=\"artikuli-explain\">DAS on usein deminutiiveilla, joiden pääte on -chen / -lein, monilla -ment / -um-päätteisillä sanoilla sekä substantiivina käytetyillä verbeillä.</p>\n\n    <h5 class=\"artikuli-subtitle\">Säännöt</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metallit → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kemialliset alkuaineet → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotellit → das Hotel</div>\n      <div class=\"kurss-example\">värit substantiiveina → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verbi substantiivina → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbit substantiiveina → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esimerkit</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — lapsi</div>\n      <div class=\"kurss-example\">das Mädchen — tyttö</div>\n      <div class=\"kurss-example\">das Häuschen — pieni talo</div>\n      <div class=\"kurss-example\">das Instrument — soitin / instrumentti</div>\n      <div class=\"kurss-example\">das Zentrum — keskusta</div>\n      <div class=\"kurss-example\">das Museum — museo</div>\n      <div class=\"kurss-example\">das Essen — syöminen / ruoka</div>\n      <div class=\"kurss-example\">das Lernen — oppiminen</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Tärkeät poikkeukset / opettele artikkelin kanssa</h4>\n    <p class=\"artikuli-explain\">Joidenkin sanojen artikkelia ei voi päätellä varmasti päätteestä, eikä suomen kielestä ole apua, koska siinä ei ole kieliopillista sukua. Nämä sanat kannattaa opetella yhdessä artikkelin kanssa.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — ovi</div>\n      <div class=\"kurss-example\">das Messer — veitsi</div>\n      <div class=\"kurss-example\">die Sonne — aurinko</div>\n      <div class=\"kurss-example\">der Mond — kuu</div>\n      <div class=\"kurss-example\">das Mädchen — tyttö</div>\n      <div class=\"kurss-example\">das Auto — auto</div>\n      <div class=\"kurss-example\">der Käse — juusto</div>\n      <div class=\"kurss-example\">die Gabel — haarukka</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Päätteet ja sanaryhmät auttavat arvaamaan artikkelin, mutta ne eivät ole 100% varma sääntö. Jos et ole varma, opettele sana yhdessä artikkelin kanssa.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronominit</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ ja Dativ — pronominien muodot.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kuka?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — minä</div><div class=\"kurss-example\">du — sinä</div><div class=\"kurss-example\">er — hän</div><div class=\"kurss-example\">sie — hän</div><div class=\"kurss-example\">es — se</div><div class=\"kurss-example\">wir — me</div><div class=\"kurss-example\">ihr — te</div><div class=\"kurss-example\">sie — he</div><div class=\"kurss-example\">Sie — Te (kohtelias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — kenet?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — minut</div><div class=\"kurss-example\">dich — sinut</div><div class=\"kurss-example\">ihn — hänet (miesp.)</div><div class=\"kurss-example\">sie — hänet (naisp.)</div><div class=\"kurss-example\">es — sen</div><div class=\"kurss-example\">uns — meidät</div><div class=\"kurss-example\">euch — teidät</div><div class=\"kurss-example\">sie — heidät</div><div class=\"kurss-example\">Sie — Teidät (kohtelias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kenelle?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — minulle</div><div class=\"kurss-example\">dir — sinulle</div><div class=\"kurss-example\">ihm — hänelle / sille</div><div class=\"kurss-example\">ihr — hänelle</div><div class=\"kurss-example\">uns — meille</div><div class=\"kurss-example\">euch — teille</div><div class=\"kurss-example\">ihnen — heille</div><div class=\"kurss-example\">Ihnen — Teille (kohtelias)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Miten muoto valitaan?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subjekti (kuka tekee?)</li><li><span class=\"case-red\">Akkusativ</span> — suora objekti (kenet?)</li><li><span class=\"case-green\">Dativ</span> — epäsuora objekti (kenelle?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Esimerkit</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Minä näen sinut.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Minä näen hänet.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Me pidämme teistä.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Minä autan sinua.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Minä annan hänelle kirjan.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Me kiitämme teitä.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ on aina lauseen subjekti, Akkusativ ja Dativ taas objekteja. Katso verbiä ja kysy: <span class=\"case-red\">kenet?</span> vai <span class=\"case-green\">kenelle?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vokaalit — pitkät ja lyhyet</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Saksassa vokaalit voivat olla pitkiä tai lyhyitä. Tämä vaikuttaa sanan ääntämiseen.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pitkä vokaali</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — lämmin</div><div class=\"kurss-example\">gut (guut) — hyvä</div><div class=\"kurss-example\">Tat (taat) — teko / toiminta</div><div class=\"kurss-example\">Flur (fluur) — eteinen / käytävä</div><div class=\"kurss-example\">Weg (veek) — tie</div><div class=\"kurss-example\">Hut (huut) — hattu</div><div class=\"kurss-example\">Hof (hoof) — piha</div><div class=\"kurss-example\">Schlaf (šlaaf) — uni</div></div>\n              <p class=\"artikuli-explain\">Jos vokaalia seuraa yksi konsonantti, vokaali äännetään usein pitkänä.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lyhyt vokaali</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — sieni</div><div class=\"kurss-example\">Wort (vort) — sana</div><div class=\"kurss-example\">Mund (munt) — suu</div><div class=\"kurss-example\">bald (balt) — pian</div><div class=\"kurss-example\">scharf (šarf) — terävä</div><div class=\"kurss-example\">Feld (felt) — pelto / kenttä</div><div class=\"kurss-example\">voll (fol) — täysi</div></div>\n              <p class=\"artikuli-explain\">Jos vokaalia seuraa kaksi tai useampia konsonantteja, vokaali äännetään usein lyhyenä.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Päätteet en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — laulaa</div><div class=\"kurss-example\">tragen (traagen) — kantaa</div><div class=\"kurss-example\">Garten (garten) — puutarha</div><div class=\"kurss-example\">Vogel (foogel) — lintu</div><div class=\"kurss-example\">Segel (zeegel) — purje</div><div class=\"kurss-example\">Braten (braaten) — paisti</div><div class=\"kurss-example\">Bogen (boogen) — kaari</div><div class=\"kurss-example\">Spiegel (špiigel) — peili</div><div class=\"kurss-example\">Finger (finger) — sormi</div><div class=\"kurss-example\">Halter (halter) — pidike</div><div class=\"kurss-example\">Arbeiter (arbaiter) — työntekijä</div><div class=\"kurss-example\">Häuser (hoizer) — talot</div><div class=\"kurss-example\">wieder (viider) — taas</div><div class=\"kurss-example\">breiter (braiter) — leveämpi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kirjain h pituuden merkkinä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (raamen) — kehys</div><div class=\"kurss-example\">Ohr (oor) — korva</div><div class=\"kurss-example\">Kohle (koole) — hiili</div><div class=\"kurss-example\">Zahl (tsaal) — luku</div><div class=\"kurss-example\">ihn (iin) — hänet / sen</div><div class=\"kurss-example\">ihm (iim) — hänelle / sille</div><div class=\"kurss-example\">Huhn (huun) — kana</div><div class=\"kurss-example\">nahm (naam) — otti</div><div class=\"kurss-example\">nehmen (neemen) — ottaa</div><div class=\"kurss-example\">Schuh (šuu) — kenkä</div></div>\n              <p class=\"artikuli-explain\">Joissakin sanoissa h pidentää edeltävää vokaalia. Tällöin h:ta ei yleensä äännetä.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>e-loppuiset sanat</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lamppu</div><div class=\"kurss-example\">Hase (haaze) — jänis</div><div class=\"kurss-example\">Knabe (knaabe) — poika</div><div class=\"kurss-example\">Rabe (raabe) — korppi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pitkä i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dii) — artikkeli ”die”</div><div class=\"kurss-example\">diese (diize) — tämä / nämä</div><div class=\"kurss-example\">wieder (viider) — taas</div><div class=\"kurss-example\">Fliege (fliige) — kärpänen</div><div class=\"kurss-example\">Ziege (tsiige) — vuohi</div><div class=\"kurss-example\">Stiel (štiil) — varsi</div><div class=\"kurss-example\">Dieb (diip) — varas</div><div class=\"kurss-example\">hier (hiir) — täällä</div></div>\n              <p class=\"artikuli-explain\">Pitkä i kirjoitetaan saksassa usein ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kaksoisvokaalit</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zaal) — sali</div><div class=\"kurss-example\">Saat (zaat) — kylvö / siemen</div><div class=\"kurss-example\">Staat (štaat) — valtio</div><div class=\"kurss-example\">Beere (beere) — marja</div><div class=\"kurss-example\">See (zee) — järvi / meri</div><div class=\"kurss-example\">Beet (beet) — kukkapenkki</div><div class=\"kurss-example\">Boot (boot) — vene</div><div class=\"kurss-example\">Moor (moor) — suo</div><div class=\"kurss-example\">Moos (moos) — sammal</div></div>\n              <p class=\"artikuli-explain\">Kaksoisvokaalit äännetään yleensä pitkinä.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — seinä</div><div class=\"kurss-example\">Wände (vende) — seinät</div><div class=\"kurss-example\">Vater (faater) — isä</div><div class=\"kurss-example\">Väter (feeter) — isät</div><div class=\"kurss-example\">Schrank (šrank) — kaappi</div><div class=\"kurss-example\">Schränke (šrenke) — kaapit</div><div class=\"kurss-example\">Bank (bank) — penkki / pankki</div><div class=\"kurss-example\">Bänke (benke) — penkit</div><div class=\"kurss-example\">Tal (taal) — laakso</div><div class=\"kurss-example\">Täler (teeler) — laaksot</div></div>\n              <p class=\"artikuli-explain\">ä on a:n umlaut-muoto.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rooze) — ruusu</div><div class=\"kurss-example\">Röschen (röös-hen) — pieni ruusu</div><div class=\"kurss-example\">Ofen (oofen) — uuni</div><div class=\"kurss-example\">Öfen (ööfen) — uunit</div><div class=\"kurss-example\">Rock (rok) — hame</div><div class=\"kurss-example\">Röcke (röke) — hameet</div></div>\n              <p class=\"artikuli-explain\">ö on o:n umlaut-muoto.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurts) — lyhyt</div><div class=\"kurss-example\">kürzer (kyrtser) — lyhyempi</div><div class=\"kurss-example\">Kunst (kunst) — taide</div><div class=\"kurss-example\">Künste (kynste) — taiteet</div><div class=\"kurss-example\">Mutter (muter) — äiti</div><div class=\"kurss-example\">Mütter (myter) — äidit</div></div>\n              <p class=\"artikuli-explain\">ü on u:n umlaut-muoto (äännetään kuten suomen y).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongit: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — puu</div><div class=\"kurss-example\">Bäume (boime) — puut</div><div class=\"kurss-example\">Haus (haus) — talo</div><div class=\"kurss-example\">Häuser (hoizer) — talot</div><div class=\"kurss-example\">Strauch (štrauh) — pensas</div><div class=\"kurss-example\">Sträucher (štroiher) — pensaat</div><div class=\"kurss-example\">Maus (maus) — hiiri</div><div class=\"kurss-example\">Mäuse (moize) — hiiret</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongit: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hoite) — tänään</div><div class=\"kurss-example\">Leute (loite) — ihmiset</div><div class=\"kurss-example\">neu (noi) — uusi</div><div class=\"kurss-example\">neun (noin) — yhdeksän</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongit: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (main) — minun</div><div class=\"kurss-example\">dein (dain) — sinun</div><div class=\"kurss-example\">sein (zain) — hänen / sen / olla</div><div class=\"kurss-example\">frei (frai) — vapaa</div><div class=\"kurss-example\">arbeiten (arbaiten) — tehdä työtä</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>2. oppitunnin ääntämishuomiot</h4>\n              <ul class=\"kurss-summary-list\"><li>sanoissa ich, nicht, rechnen, zeichnen ”ch” äännetään pehmeästi (kuten h sanassa ”ihminen”)</li><li>sanoissa arbeiten ja zeichnen ”ei” äännetään kuten ”ai”</li><li>”sp” äännetään sanan alussa kuten ”šp” (š = englannin sh)</li><li>verbissä tun kirjain ”u” äännetään pitkänä (kuten ”uu”)</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Yhteenveto</h4>\n              <ul class=\"kurss-summary-list\"><li>yksi konsonantti vokaalin jälkeen → usein pitkä vokaali</li><li>kaksi tai useampia konsonantteja → usein lyhyt vokaali</li><li>h voi pidentää vokaalia</li><li>ie tarkoittaa usein pitkää i:tä (”ii”)</li><li>kaksoisvokaalit ovat yleensä pitkiä</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Konsonantit ja kirjainyhdistelmät</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Saksassa jotkin konsonantit ja kirjainyhdistelmät äännetään eri tavalla kuin ne kirjoitetaan. Tässä oppitunnissa ovat aloittelijalle tärkeimmät esimerkit.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Konsonantit</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (raat) — pyörä</div><div class=\"kurss-example\">die Räder (reeder) — pyörät</div><div class=\"kurss-example\">Bad (baat) — kylpy / kylpyhuone</div><div class=\"kurss-example\">Bäder (beeder) — kylvyt / kylpyhuoneet</div></div>\n              <p class=\"artikuli-explain\">Sanan lopussa konsonantteja ei usein äännetä samoin kuin ne kirjoitetaan (esim. d äännetään kuten t).</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">”ch” voidaan ääntää pehmeästi tai kovasti. Joissakin sanoissa se kuulostaa kuin pehmeä ”h” (kuten sanassa ”ihminen”), toisissa lähempänä käheää ”k”:ta (kuten h sanassa ”tahto”, voimakkaammin).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehnen) — laskea</div><div class=\"kurss-example\">zeichnen (tsaihnen) — piirtää</div><div class=\"kurss-example\">nicht (niht) — ei</div><div class=\"kurss-example\">schlecht (šleht) — huono</div><div class=\"kurss-example\">mich (mih) — minut</div><div class=\"kurss-example\">dich (dih) — sinut</div><div class=\"kurss-example\">Strauch (štrauh) — pensas</div><div class=\"kurss-example\">noch (noh) — vielä</div><div class=\"kurss-example\">Nacht (naht) — yö</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">”sch” äännetään saksassa kuten ”š” (englannin ”sh”, suomen sanassa ”šakki”).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (šuule) — koulu</div><div class=\"kurss-example\">Schüler (šyyler) — oppilas</div><div class=\"kurss-example\">Schiff (šif) — laiva</div><div class=\"kurss-example\">Schraube (šraube) — ruuvi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp ja st sanan alussa</h4>\n              <p class=\"artikuli-explain\">Sanan tai tavun alussa ”sp” äännetään usein kuten ”šp” ja ”st” kuten ”št”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (špiilen) — leikkiä / pelata</div><div class=\"kurss-example\">Sprung (šprung) — hyppy</div><div class=\"kurss-example\">stehen (štee-en) — seistä</div><div class=\"kurss-example\">Stall (štal) — talli</div><div class=\"kurss-example\">Stand (štant) — asema / paikka</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">”qu” äännetään saksassa yleensä kuten ”kv”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvaal) — tuska</div><div class=\"kurss-example\">Quartier (kvartiir) — majapaikka / kortteli</div><div class=\"kurss-example\">quer (kveer) — poikittain</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s ja z</h4>\n              <p class=\"artikuli-explain\">Sanan alussa ”s” kuulostaa usein soinnilliselta ”z”:lta (kuten englannin sanassa ”zoo”; ääntämisohjeissa merkitään z). Kirjain ”z” äännetään saksassa kuten ”ts”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zaagen) — sanoa</div><div class=\"kurss-example\">singen (zingen) — laulaa</div><div class=\"kurss-example\">Rose (rooze) — ruusu</div><div class=\"kurss-example\">Zahl (tsaal) — luku</div><div class=\"kurss-example\">Zeit (tsait) — aika</div><div class=\"kurss-example\">Zink (tsink) — sinkki</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">Saksassa ”v” äännetään usein kuten ”f”. Vierasperäisissä sanoissa se kuulostaa usein suomen ”v”:ltä.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (faater) — isä</div><div class=\"kurss-example\">von (fon) — -sta / -lta (prepositio von)</div><div class=\"kurss-example\">viel (fiil) — paljon</div><div class=\"kurss-example\">vier (fiir) — neljä</div><div class=\"kurss-example\">Villa (vila) — huvila</div><div class=\"kurss-example\">Klavier (klaviir) — piano</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x ja y</h4>\n              <p class=\"artikuli-explain\">”x” äännetään kuten ”ks”. ”y” äännetään joissakin sanoissa kuten ”ü” (suomen ”y”).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (feeliks) — Felix (nimi)</div><div class=\"kurss-example\">Axt (akst) — kirves</div><div class=\"kurss-example\">Mystik (mystik) — mystiikka</div><div class=\"kurss-example\">Mythe (myyte) — myytti</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">”ß” äännetään saksassa kuten soinniton ”s”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fuus) — jalka / jalkaterä</div><div class=\"kurss-example\">Füße (fyyse) — jalat / jalkaterät</div><div class=\"kurss-example\">Grüße (gryyse) — terveiset</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Yhteenveto</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š (sh)</li><li>sp / st alussa → šp / št</li><li>qu → kv</li><li>z → ts</li><li>v usein → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Verbien perusteet</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>1. oppitunnin verbit ja niiden muodot (taivutus)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Verbit</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — tulla</div><div class=\"kurss-example\">gehen — mennä</div><div class=\"kurss-example\">stehen — seistä</div><div class=\"kurss-example\">singen — laulaa</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — minä tulen</div><div class=\"kurss-example\">du kommst — sinä tulet</div><div class=\"kurss-example\">er kommt — hän tulee</div><div class=\"kurss-example\">sie kommt — hän tulee</div><div class=\"kurss-example\">wir kommen — me tulemme</div><div class=\"kurss-example\">ihr kommt — te tulette</div><div class=\"kurss-example\">sie kommen — he tulevat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — minä menen</div><div class=\"kurss-example\">du gehst — sinä menet</div><div class=\"kurss-example\">er geht — hän menee</div><div class=\"kurss-example\">sie geht — hän menee</div><div class=\"kurss-example\">wir gehen — me menemme</div><div class=\"kurss-example\">ihr geht — te menette</div><div class=\"kurss-example\">sie gehen — he menevät</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — minä seison</div><div class=\"kurss-example\">du stehst — sinä seisot</div><div class=\"kurss-example\">er steht — hän seisoo</div><div class=\"kurss-example\">sie steht — hän seisoo</div><div class=\"kurss-example\">wir stehen — me seisomme</div><div class=\"kurss-example\">ihr steht — te seisotte</div><div class=\"kurss-example\">sie stehen — he seisovat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — minä laulan</div><div class=\"kurss-example\">du singst — sinä laulat</div><div class=\"kurss-example\">er singt — hän laulaa</div><div class=\"kurss-example\">sie singt — hän laulaa</div><div class=\"kurss-example\">wir singen — me laulamme</div><div class=\"kurss-example\">ihr singt — te laulatte</div><div class=\"kurss-example\">sie singen — he laulavat</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>2. oppitunnin verbit</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — pelata</div><div class=\"kurss-example\">arbeiten — työskennellä</div><div class=\"kurss-example\">fragen — kysyä</div><div class=\"kurss-example\">antworten — vastata</div><div class=\"kurss-example\">rechnen — laskea</div><div class=\"kurss-example\">zeichnen — piirtää</div><div class=\"kurss-example\">tun — tehdä</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — minä pelaan</div><div class=\"kurss-example\">du spielst — sinä pelaat</div><div class=\"kurss-example\">er spielt — hän pelaa</div><div class=\"kurss-example\">sie spielt — hän pelaa</div><div class=\"kurss-example\">wir spielen — me pelaamme</div><div class=\"kurss-example\">ihr spielt — te pelaatte</div><div class=\"kurss-example\">sie spielen — he pelaavat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — minä työskentelen</div><div class=\"kurss-example\">du arbeitest — sinä työskentelet</div><div class=\"kurss-example\">er arbeitet — hän työskentelee</div><div class=\"kurss-example\">sie arbeitet — hän työskentelee</div><div class=\"kurss-example\">wir arbeiten — me työskentelemme</div><div class=\"kurss-example\">ihr arbeitet — te työskentelette</div><div class=\"kurss-example\">sie arbeiten — he työskentelevät</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — minä kysyn</div><div class=\"kurss-example\">du fragst — sinä kysyt</div><div class=\"kurss-example\">er fragt — hän kysyy</div><div class=\"kurss-example\">sie fragt — hän kysyy</div><div class=\"kurss-example\">wir fragen — me kysymme</div><div class=\"kurss-example\">ihr fragt — te kysytte</div><div class=\"kurss-example\">sie fragen — he kysyvät</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — minä vastaan</div><div class=\"kurss-example\">du antwortest — sinä vastaat</div><div class=\"kurss-example\">er antwortet — hän vastaa</div><div class=\"kurss-example\">sie antwortet — hän vastaa</div><div class=\"kurss-example\">wir antworten — me vastaamme</div><div class=\"kurss-example\">ihr antwortet — te vastaatte</div><div class=\"kurss-example\">sie antworten — he vastaavat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — minä lasken</div><div class=\"kurss-example\">du rechnest — sinä lasket</div><div class=\"kurss-example\">er rechnet — hän laskee</div><div class=\"kurss-example\">sie rechnet — hän laskee</div><div class=\"kurss-example\">wir rechnen — me laskemme</div><div class=\"kurss-example\">ihr rechnet — te laskette</div><div class=\"kurss-example\">sie rechnen — he laskevat</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — minä piirrän</div><div class=\"kurss-example\">du zeichnest — sinä piirrät</div><div class=\"kurss-example\">er zeichnet — hän piirtää</div><div class=\"kurss-example\">sie zeichnet — hän piirtää</div><div class=\"kurss-example\">wir zeichnen — me piirrämme</div><div class=\"kurss-example\">ihr zeichnet — te piirrätte</div><div class=\"kurss-example\">sie zeichnen — he piirtävät</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — minä teen</div><div class=\"kurss-example\">du tust — sinä teet</div><div class=\"kurss-example\">er tut — hän tekee</div><div class=\"kurss-example\">sie tut — hän tekee</div><div class=\"kurss-example\">wir tun — me teemme</div><div class=\"kurss-example\">ihr tut — te teette</div><div class=\"kurss-example\">sie tun — he tekevät</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Lauserakenne</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Kysymyslauseessa verbi on saksan kielessä yleensä ensimmäisellä paikalla.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Esimerkit</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Sinä tulet.</div><div class=\"kurss-example\">Kommst du? — Tuletko sinä?</div><div class=\"kurss-example\">Er singt. — Hän laulaa.</div><div class=\"kurss-example\">Singt er? — Laulaako hän?</div><div class=\"kurss-example\">Stehst du? — Seisotko sinä?</div><div class=\"kurss-example\">Ja, ich stehe. — Kyllä, minä seison.</div><div class=\"kurss-example\">Geht ihr? — Menettekö te?</div><div class=\"kurss-example\">Ja, wir gehen. — Kyllä, me menemme.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kysymykset sanalla ”was”</h4>\n              <p class=\"artikuli-explain\">Jos kysymys alkaa kysymyssanalla, verbi on saksan kielessä yleensä heti kysymyssanan jälkeen.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Mitä sinä teet?</div><div class=\"kurss-example\">Was tut er? — Mitä hän tekee?</div><div class=\"kurss-example\">Was tut sie? — Mitä hän tekee?</div><div class=\"kurss-example\">Was tun sie? — Mitä he tekevät?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kielto sanalla ”nicht”</h4>\n              <p class=\"artikuli-explain\">Jos kieltosana ”nicht” koskee verbiä, se on saksan kielessä yleensä verbin jälkeen.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Minä en pelaa.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul ei kysy.</div><div class=\"kurss-example\">Er kommt nicht. — Hän ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — He eivät laula.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lauseet 2. oppitunnilta</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Pelaatko sinä?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ei, minä en pelaa, minä teen töitä.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul ei kysy, hän tekee töitä.</div><div class=\"kurss-example\">Arbeitest du? — Teetkö sinä töitä?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ei, minä en tee töitä, minä laulan.</div><div class=\"kurss-example\">Was tut Paul? — Mitä Paul tekee?</div><div class=\"kurss-example\">Er spielt. — Hän pelaa.</div><div class=\"kurss-example\">Was tut Marie? — Mitä Marie tekee?</div><div class=\"kurss-example\">Sie singt. — Hän laulaa.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul pelaa, mutta Marie laulaa.</div><div class=\"kurss-example\">Singt ihr? — Laulatteko te?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ei, me emme laula, me teemme töitä.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Mitä Paul ja Marie tekevät?</div><div class=\"kurss-example\">Sie fragen. — He kysyvät.</div><div class=\"kurss-example\">Sie antworten nicht. — He eivät vastaa.</div><div class=\"kurss-example\">Wer arbeitet? — Kuka tekee töitä?</div><div class=\"kurss-example\">Wir arbeiten. — Me teemme töitä.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Me laskemme ja piirrämme.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — He tulevat, kysyvät, vastaavat, tekevät töitä, pelaavat, laulavat ja menevät.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Oppitunti 1</h3>\n            <p class=\"kurss-lesson-intro\">Ensimmäinen oppitunti: verbit preesensissä, sanasto, ääntäminen, kielioppi ja kääntäminen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbit preesensissä</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verbit ja niiden taivutus preesensissä.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — tulla</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>minä tulen</span><span>du</span><strong>kommst</strong><span>sinä tulet</span><span>er / sie</span><strong>kommt</strong><span>hän tulee</span><span>wir</span><strong>kommen</strong><span>me tulemme</span><span>ihr</span><strong>kommt</strong><span>te tulette</span><span>sie / Sie</span><strong>kommen</strong><span>he tulevat / Te tulette</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — mennä</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>minä menen</span><span>du</span><strong>gehst</strong><span>sinä menet</span><span>er / sie</span><strong>geht</strong><span>hän menee</span><span>wir</span><strong>gehen</strong><span>me menemme</span><span>ihr</span><strong>geht</strong><span>te menette</span><span>sie / Sie</span><strong>gehen</strong><span>he menevät / Te menette</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — seistä</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>minä seison</span><span>du</span><strong>stehst</strong><span>sinä seisot</span><span>er / sie</span><strong>steht</strong><span>hän seisoo</span><span>wir</span><strong>stehen</strong><span>me seisomme</span><span>ihr</span><strong>steht</strong><span>te seisotte</span><span>sie / Sie</span><strong>stehen</strong><span>he seisovat / Te seisotte</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — laulaa</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>minä laulan</span><span>du</span><strong>singst</strong><span>sinä laulat</span><span>er / sie</span><strong>singt</strong><span>hän laulaa</span><span>wir</span><strong>singen</strong><span>me laulamme</span><span>ihr</span><strong>singt</strong><span>te laulatte</span><span>sie / Sie</span><strong>singen</strong><span>he laulavat / Te laulatte</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Esimerkit</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Sanojen likimääräinen ääntämys on annettu suluissa suomalaisin kirjaimin.<br>Tämä on huomattava myös seuraavilla oppitunneilla.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — me</div><div class=\"kurss-example\">Sanassa “wir” i äännetään pitkänä.</div><div class=\"kurss-example\">kommen (komen) — tulla</div><div class=\"kurss-example\">gehen (gee-en) — mennä</div><div class=\"kurss-example\">stehen (shtee-en) — seistä</div><div class=\"kurss-example\">singen (zingen) — laulaa</div><div class=\"kurss-example\">du (duu) kommst — sinä tulet</div><div class=\"kurss-example\">er (eer) kommt — hän (mies) tulee</div><div class=\"kurss-example\">sie (zii) kommt — hän (nainen) tulee</div><div class=\"kurss-example\">wer (veer) — kuka?</div><div class=\"kurss-example\">ja (jaa) — kyllä</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sanojen oikea ääntämys on annettu oppitunneilla suomalaisin kirjaimin.</div><div class=\"kurss-example\">Wir (viir) — me. Sanassa wir i äännetään aina pitkänä.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiivi</h4><div class=\"lesson1-grammar-note\">Verbin perusmuoto. Infinitiivi päättyy yleensä päätteeseen -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Preesensin päätteet</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Poista <span class=\"lesson1-ending-accent\">-en</span> verbin perusmuodosta ja lisää pääte.</strong></p><p>Esimerkki: kommen → komm + pääte</p><div class=\"lesson1-ending-process\" aria-label=\"Preesenspäätteiden muodostaminen\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>perusmuoto</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>poista <span class=\"lesson1-ending-accent\">-en</span></strong><span>jäljelle jää vartalo</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>vartalo</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>lisää pääte</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Esimerkit</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Kysymyslauseet</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Saksan kysymyslauseessa verbi siirtyy yleensä ensimmäiselle paikalle.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Suomeksi:<br>Sinä tulet.<br>Tuletko sinä?</div><div class=\"kurss-example\">Saksaksi:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — sinä tulet<br>kommst du? — tuletko sinä?</div><div class=\"kurss-example\">er singt — hän laulaa<br>singt er? — laulaako hän?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Persoonan ero</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — hän (mies) tulee</div><div class=\"kurss-example\">sie kommt — hän (nainen) tulee</div><div class=\"kurss-example\">sie kommen — he tulevat</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 1: harjoituskortti\">\n                    <span class=\"lesson1-training-progress\">Oppitunti 1 · Käännä: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Tuletko sinä?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Oppitunti 2</h3>\n            <p class=\"kurss-lesson-intro\">Toinen oppitunti: dialogit, sanasto, ääntäminen, kielioppi ja kääntäminen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — leikkiä; pelata, soittaa</div>\n                  <div class=\"kurss-example\">nein — ei</div>\n                  <div class=\"kurss-example\">nicht — ei (kieltosana)</div>\n                  <div class=\"kurss-example\">arbeiten — tehdä työtä</div>\n                  <div class=\"kurss-example\">fragen — kysyä</div>\n                  <div class=\"kurss-example\">was tut er? — mitä hän tekee?</div>\n                  <div class=\"kurss-example\">was tun sie? — mitä he tekevät?</div>\n                  <div class=\"kurss-example\">aber — mutta</div>\n                  <div class=\"kurss-example\">antworten — vastata</div>\n                  <div class=\"kurss-example\">rechnen — laskea (laskutoimituksia)</div>\n                  <div class=\"kurss-example\">zeichnen — piirtää</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sanoissa ich, nicht, rechnen, zeichnen ch äännetään pehmeästi, suunnilleen kuten h suomen sanoissa ihminen, lehti.</div><div class=\"kurss-example\">Sanoissa arbeiten, zeichnen diftongi ei äännetään suunnilleen kuten suomen ai.</div><div class=\"kurss-example\">Konsonanttiyhtymä sp äännetään kuten shp: spielen (shpiilen).</div><div class=\"kurss-example\">Verbissä tun u äännetään pitkänä kaikissa persoonissa.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Päätteet, joissa on e</h4>\n                  <div class=\"lesson1-grammar-note\">Jos verbin vartalo päättyy t:hen, d:hen tai chn:ään, taivutuksessa päätteiden -st ja -t eteen tulee e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Kysymyssana</h4>\n                  <div class=\"lesson1-grammar-note\">Kysymyslauseissa, jotka alkavat kysymyssanalla, esimerkiksi mitä? kuka? mikä? miksi? minkä vuoksi? jne., verbi tulee heti kysymyssanan jälkeen.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Mitä sinä teet?</div><div class=\"kurss-example\">Was tut er? — Mitä hän (mies) tekee?</div><div class=\"kurss-example\">Was tut sie? — Mitä hän (nainen) tekee?</div><div class=\"kurss-example\">Was tun sie? — Mitä he tekevät?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Kielto sanalla nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Jos kieltosana nicht kohdistuu verbiin, se sijoittuu verbin jälkeen.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Hän ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — He eivät laula.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 2: käännöskortti\">\n                    <span class=\"lesson1-training-progress\">Oppitunti 2 · Käännä: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kuka kysyy?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Oppitunti 3</h3>\n            <p class=\"kurss-lesson-intro\">Kolmas oppitunti: dialogit, sanasto, ääntäminen, kielioppi ja kääntäminen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kuka</div><div class=\"kurss-example\">was — mikä</div><div class=\"kurss-example\">hier — täällä</div><div class=\"kurss-example\">dort — siellä</div><div class=\"kurss-example\">der Tisch — pöytä</div><div class=\"kurss-example\">ein Tisch — pöytä</div><div class=\"kurss-example\">die Bank — penkki</div><div class=\"kurss-example\">eine Bank — penkki</div><div class=\"kurss-example\">liegen — maata, olla vaakatasossa</div><div class=\"kurss-example\">liegt hier ein Buch? — onko täällä kirja?</div><div class=\"kurss-example\">das Buch — kirja</div><div class=\"kurss-example\">ein Buch — kirja</div><div class=\"kurss-example\">hängen — riippua</div><div class=\"kurss-example\">das Bild — kuva, taulu</div><div class=\"kurss-example\">ein Bild — kuva, taulu</div><div class=\"kurss-example\">die Tafel — liitutaulu</div><div class=\"kurss-example\">eine Tafel — liitutaulu</div><div class=\"kurss-example\">wie — millainen</div><div class=\"kurss-example\">ist — on</div><div class=\"kurss-example\">dick — paksu, lihava</div><div class=\"kurss-example\">das Heft — vihko</div><div class=\"kurss-example\">ein Heft — vihko</div><div class=\"kurss-example\">dünn — ohut, laiha</div><div class=\"kurss-example\">niedrig — matala</div><div class=\"kurss-example\">hoch — korkea</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pitkä i-äänne merkitään saksassa ie:llä: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck on kaksinkertainen k: dick (dikk).</div><div class=\"kurss-example\">Adjektiiveissa ja adverbeissa pääte -ig äännetään kuten kevyt -ich: niedrig (niidrih).</div><div class=\"kurss-example\">Jos päätettä -ig seuraa e: -ige, g äännetään selvänä g-äänteenä: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subjekti</h4><div class=\"lesson1-grammar-note\">Saksassa subjekti vastaa kysymykseen wer? / was? ja on nominatiivissa.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kysymyksellä wer? kysytään henkilöitä.</div><div class=\"kurss-example\">Kysymyksellä was? kysytään esineitä.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikkelit</h4><div class=\"lesson1-grammar-note\">Saksan substantiiveilla on 3 sukua: maskuliini, feminiini ja neutri. Substantiivin edessä on yleensä pieni sana, jota kutsutaan artikkeliksi. Tätä sanaa ei käännetä.</div><h5 class=\"lesson2-subtitle\">Määräinen artikkeli</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maskuliini — der</div><div class=\"kurss-example\">feminiini — die</div><div class=\"kurss-example\">neutri — das</div><div class=\"kurss-example\">Monikossa määräinen artikkeli on kaikissa kolmessa suvussa die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Epämääräinen artikkeli</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maskuliini — ein</div><div class=\"kurss-example\">feminiini — eine</div><div class=\"kurss-example\">neutri — ein</div><div class=\"kurss-example\">Epämääräisellä artikkelilla ei ole monikkoa.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Erisnimet</h4><div class=\"lesson1-grammar-note\">Erisnimien edessä ei käytetä artikkelia.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbin paikka</h4><div class=\"lesson1-grammar-note\">Väitelauseessa verbi on toisella paikalla.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Saksassa pystyasennossa olevista esineistä sanotaan, että esine seisoo:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Vaaka-asennossa olevista esineistä sanotaan, että ne makaavat:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Esineet voivat myös riippua:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 3: käännöskortti\"><span class=\"lesson1-training-progress\">Oppitunti 3 · Käännä: 1 / 22</span><span class=\"lesson1-training-text\">Lasketko sinä?</span></button><p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p></div></div></details>",
  "kurssLesson4": "            <h3>Oppitunti 4</h3>\n            <p class=\"kurss-lesson-intro\">Akkusatiivi, nehmen, hinlegen, hinausgehen ja adjektiivit.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — ottaa</div><div class=\"kurss-example\">er nimmt (nimt) — hän ottaa</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — kynänvarsi</div><div class=\"kurss-example\">einen Federhalter — kynänvarren</div><div class=\"kurss-example\">zeigen — näyttää</div><div class=\"kurss-example\">schwarz (shvarts) — musta</div><div class=\"kurss-example\">weiß (vais) — valkoinen</div><div class=\"kurss-example\">die Feder (dii feeder) — kynänterä</div><div class=\"kurss-example\">eine Feder — kynänterän</div><div class=\"kurss-example\">spitz (shpits) — suippo, terävä</div><div class=\"kurss-example\">hinlegen — panna pois</div><div class=\"kurss-example\">legt hin — panee pois</div><div class=\"kurss-example\">das Mädchen (meet-hen) — tyttö</div><div class=\"kurss-example\">das Messer — veitsi</div><div class=\"kurss-example\">ein Messer — veitsen</div><div class=\"kurss-example\">scharf — terävä</div><div class=\"kurss-example\">stumpf (shtumpf) — tylsä, tylppä</div><div class=\"kurss-example\">dann — sitten</div><div class=\"kurss-example\">hinaus — ulos</div><div class=\"kurss-example\">hinausgehen — mennä ulos</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Päätteet -en, -er, -el ovat painottomia, joten e kuuluu niissä heikosti: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Saksassa h voi olla joko äänne tai edeltävän vokaalin pituuden merkki.</div><div class=\"kurss-example\">Jos h on pituuden merkki, sitä ei äännetä: nehmen (neemen).</div><div class=\"kurss-example\">Jos vokaalia seuraa vain yksi konsonantti, vokaali äännetään pitkänä: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akkusatiivi</h4><div class=\"lesson1-grammar-note\">Feminiinissä ja neutrissa akkusatiivi on sama kuin nominatiivi. Vain maskuliini muuttuu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronominit</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — maskuliini</div><div class=\"kurss-example\">sie — feminiini</div><div class=\"kurss-example\">es — neutri</div><div class=\"kurss-example\">monikossa — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Erotettavat verbit</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjektiivit</h4><div class=\"lesson1-grammar-note\">Jos adjektiivi on lauseessa predikatiivina, se ei muutu suvun eikä luvun mukaan.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Kielto sanalla nicht</h4><div class=\"lesson1-grammar-note\">Jos nicht kieltää adjektiivin, se sijoittuu kiellettävän sanan eteen.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Substantiivit, joiden pääte on -chen tai -lein, ovat neutreja: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 4: käännöskortti\"><span class=\"lesson1-training-progress\">Oppitunti 4 · Käännä: 1 / 16</span><span class=\"lesson1-training-text\">Tyttö ottaa kynänvarren.</span></button><p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Oppitunti 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akkusatiivi, sitzen, fragen ja pääte -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (tsitsen) — istua</div>\n        <div class=\"kurss-example\">fragen (fraagen) — kysyä</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — opettaja</div>\n        <div class=\"kurss-example\">gut (guut) — hyvin</div>\n        <div class=\"kurss-example\">wen (veen) — kenet, ketä</div>\n        <div class=\"kurss-example\">loben — kehua</div>\n        <div class=\"kurss-example\">der Schüler (shyyler) — oppilas</div>\n        <div class=\"kurss-example\">klein — pieni</div>\n        <div class=\"kurss-example\">groß (groos) — suuri</div>\n        <div class=\"kurss-example\">die Lehrerin — naisopettaja</div>\n        <div class=\"kurss-example\">die Schülerin — tyttöoppilas</div>\n        <div class=\"kurss-example\">schlecht (shleht) — huonosti</div>\n        <div class=\"kurss-example\">tadeln — moittia</div>\n        <div class=\"kurss-example\">oder (ooder) — tai, vai</div>\n        <div class=\"kurss-example\">das Kind (kint) — lapsi</div>\n        <div class=\"kurss-example\">artig (aartih) — kiltti</div>\n        <div class=\"kurss-example\">die Mutter — äiti</div>\n        <div class=\"kurss-example\">lieben (liiben) — rakastaa</div>\n        <div class=\"kurss-example\">der Vater (faater) — isä</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz on kaksinkertainen z-äänne, ja se äännetään kuten ts: sitzen (tsitsen).</div>\n        <div class=\"kurss-example\">Saksan sanoissa v äännetään kuten f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß:n nimi on Eszett, ja se äännetään kuten suomen s: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatiivi ja akkusatiivi</h4><div class=\"lesson1-grammar-note\">Suomessa subjekti vastaa kysymykseen kuka? mikä?, objekti taas kysymykseen kenet? minkä?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Saksassa nominatiivin kysymys on henkilöistä wer? ja esineistä was?.</div><div class=\"kurss-example\">Akkusatiivin kysymys on henkilöistä wen? ja esineistä was?.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artikkelien muuttuminen akkusatiivissa</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akkusatiivi</h4><div class=\"lesson1-grammar-note\">Saksan verbi fragen vaatii akkusatiivin.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Pääte -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Monet feminiinisanat johdetaan päätteellä -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verbin paikka</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Väitelauseessa verbi on toisella paikalla.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 5: käännöskortti\"><span class=\"lesson1-training-progress\">Oppitunti 5 · Käännä: 1 / 16</span><span class=\"lesson1-training-text\">Ketä isä rakastaa?</span></button><p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Oppitunti 6</h3>\n    <p class=\"kurss-lesson-intro\">Lukusanat, monikko, umlautit ja substantiivien monikkomuodot.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — sijaitsee, on, makaa</div><div class=\"kurss-example\">der Bleistift (blaishtift) — lyijykynä</div><div class=\"kurss-example\">einige (ainige) — muutamat, jotkut</div><div class=\"kurss-example\">hinlegen — panna pois</div><div class=\"kurss-example\">legt hin — panee pois</div><div class=\"kurss-example\">wieder (viider) — taas, jälleen</div><div class=\"kurss-example\">aufmachen — avata</div><div class=\"kurss-example\">er macht auf — hän avaa</div><div class=\"kurss-example\">anspitzen (anshpitsen) — teroittaa</div><div class=\"kurss-example\">er spitzt an — hän teroittaa</div><div class=\"kurss-example\">sich setzen — istuutua</div><div class=\"kurss-example\">setzt sich — istuutuu</div><div class=\"kurss-example\">der Schlüssel (shlyssel) — avain</div><div class=\"kurss-example\">das Fenster (fenster) — ikkuna</div><div class=\"kurss-example\">die Tafel (dii taafel) — liitutaulu</div><div class=\"kurss-example\">der Garten — puutarha</div><div class=\"kurss-example\">der Löffel — lusikka</div><div class=\"kurss-example\">zählen (tseelen) — laskea (lukumäärää)</div><div class=\"kurss-example\">die Nadel — neula</div><div class=\"kurss-example\">was ist das — mikä tämä on?</div><div class=\"kurss-example\">der Hammer — vasara</div><div class=\"kurss-example\">die Hämmer — vasarat</div><div class=\"kurss-example\">der Deckel (deer dekel) — kansi</div><div class=\"kurss-example\">der Teller — lautanen</div><div class=\"kurss-example\">der Wagen — kärryt</div><div class=\"kurss-example\">der Schlitten — reki, kelkka</div><div class=\"kurss-example\">das Ding — asia, esine</div><div class=\"kurss-example\">die Dinge — asiat, esineet</div><div class=\"kurss-example\">wie sind die Dinge? — millaisia esineet ovat?</div><div class=\"kurss-example\">voll (foll) — täysi, täynnä</div><div class=\"kurss-example\">leer (leer) — tyhjä</div><div class=\"kurss-example\">schwer (shveer) — painava, vaikea</div><div class=\"kurss-example\">leicht — kevyt</div><div class=\"kurss-example\">der Eimer — ämpäri</div><div class=\"kurss-example\">wieviel (viifiil) — kuinka monta, paljonko</div><div class=\"kurss-example\">wieviel Nadeln — kuinka monta neulaa</div><div class=\"kurss-example\">hier (hiir) — täällä</div><div class=\"kurss-example\">dort — siellä</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä on vokaalin a umlaut, ja se äännetään kuten lyhyt tai pitkä suppea e.</div><div class=\"kurss-example\">Esimerkkejä: das Mädchen (meet-hen), die Bänke (dii benke), der Vater (deer faater), die Väter (dii feeter).</div><div class=\"kurss-example\">ü on vokaalin u umlaut, ja se äännetään kuten suomen y. Sitä äännettäessä huulet pyöristetään voimakkaasti ja pyöristetyin huulin yritetään sanoa i.</div><div class=\"kurss-example\">Esimerkkejä: fünf, der Schlüssel (shlyssel).</div><div class=\"kurss-example\">ö äännetään kuten suomen ö, pyöristetyin huulin e:tä sanoen: der Löffel.</div><div class=\"kurss-example\">Kaksinkertainen vokaali merkitsee pitkää vokaalia: leer (leer).</div><div class=\"kurss-example\">Diftongi eu äännetään kuten oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Kielioppi ja selitykset</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Yhdysverbin painollinen etuliite irtoaa preesensissä verbistä ja sijoittuu lauseen loppuun.</div><div class=\"kurss-example\">Esimerkkejä: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Lukusanalla yksi on kaikki kolme sukua, kun sitä käytetään substantiivin kanssa: maskuliinissa ein, feminiinissä eine, neutrissa ein.</div><div class=\"kurss-example\">Esimerkkejä: ein Schüler — yksi oppilas; eine Schülerin — yksi tyttöoppilas; ein Kind — yksi lapsi.</div><div class=\"kurss-example\">Lukusanat: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">Saksan kopulaverbillä on yksikkö- ja monikkomuoto: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Suomen osoittava pronomini tämä muuttuu monikossa muotoon nämä, mutta saksassa käytetään vain yhtä muotoa: das.</div><div class=\"kurss-example\">Esimerkkejä: tämä on vasara — das ist ein Hammer; tämä on neula — das ist eine Nadel; nämä ovat vasaroita — das sind Hämmer; nämä ovat neuloja — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — kärryt on suomessa monikkosana, mutta saksassa sekä sitä että sanaa der Schlitten — reki käytetään yksikössä ja monikossa.</div><div class=\"kurss-example\">Maskuliini- ja neutrisubstantiivit, joiden pääte on -er, -el tai -en, eivät monikossa usein saa päätettä.</div><div class=\"kurss-example\">Esimerkkejä: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Feminiinisubstantiivit, joiden pääte on -el tai -er, saavat monikossa päätteen -n.</div><div class=\"kurss-example\">Esimerkkejä: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Poikkeukset: die Mutter (äiti) — die Mütter (äidit); die Tochter (tytär) — die Töchter (tyttäret).</div><div class=\"kurss-example\">Epämääräisellä artikkelilla ei ole monikkoa: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Väitelauseessa predikaattiverbi on toisella paikalla: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Käännä</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 6: käännöskortti\"><span class=\"lesson1-training-progress\">Oppitunti 6 · Käännä: 1 / 21</span><span class=\"lesson1-training-text\">Paul ottaa lyijykynän ja piirtää.</span></button><p class=\"lesson1-training-hint\">Napsauta korttia nähdäksesi saksankielisen käännöksen. Vastauksen jälkeen seuraava napsautus näyttää seuraavan kortin.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Oppitunti 7</h3>\n            <p class=\"kurss-lesson-intro\">Seitsemäs oppitunti: imperatiivi, kohtelias puhuttelumuoto ja monikko.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogit / lauseet</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sanasto</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — laulaa</div><div class=\"kurss-example\">singe — laula</div><div class=\"kurss-example\">singt — laulakaa</div><div class=\"kurss-example\">singen Sie — laulakaa</div><div class=\"kurss-example\">das Lied (das liit) — laulu</div><div class=\"kurss-example\">Sie — Te</div><div class=\"kurss-example\">zählen — laskea (lukumäärää)</div><div class=\"kurss-example\">das Fräulein (froilain) — neiti</div><div class=\"kurss-example\">der Müller — mylläri</div><div class=\"kurss-example\">öffnen — avata</div><div class=\"kurss-example\">das Fenster (fenster) — ikkuna</div><div class=\"kurss-example\">alle — kaikki</div><div class=\"kurss-example\">der Spiegel (shpiigel) — peili</div><div class=\"kurss-example\">der Lappen — rätti, riepu</div><div class=\"kurss-example\">der Spaten — lapio</div><div class=\"kurss-example\">der Besen — luuta</div><div class=\"kurss-example\">die Schaufel — pieni lapio, kola</div><div class=\"kurss-example\">die Schüssel — kulho</div><div class=\"kurss-example\">das Zimmer — huone</div><div class=\"kurss-example\">das Ufer (uufer) — ranta</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Ääntäminen</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp äännetään sanan tai tavun alussa kuten shp: der Spiegel (deer shpiigel).</div><div class=\"kurss-example\">sch äännetään sh-äänteenä: die Schaufel (dii shaufel), die Schüssel (dii shyssel).</div><div class=\"kurss-example\">Diftongi äu äännetään kuten suomen oi: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Kielioppi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperatiivi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Yksikön 2. persoonan imperatiivi vastaa verbin yksikön 2. persoonaa ilman persoonapäätettä -st, ja siihen lisätään pääte -e.</div><div class=\"kurss-example\">Esimerkkejä: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Hyvin usein päätettä -e ei käytetä, jos käskymuoto on ilman sitä yksitavuinen: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Monikon imperatiivi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Monikon 2. persoonan imperatiivi on sama kuin preesensin monikon 2. persoona, mutta sitä käytetään ilman pronominia.</div><div class=\"kurss-example\">Esimerkkejä: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Kohtelias puhuttelumuoto Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kohtelias puhuttelumuoto ”Te” vastaa monikon 3. persoonaa. Pronomini Sie kirjoitetaan isolla alkukirjaimella, ja se sijoittuu verbin jälkeen.</div><div class=\"kurss-example\">Esimerkkejä: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Verbin öffnen yksikön 2. ja 3. persoonassa sekä monikon 2. persoonassa vartalon ja päätteen väliin lisätään ääntämisen helpottamiseksi e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Harjoitus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Oppitunti 7: harjoituskortti\"><span class=\"lesson1-training-progress\">Oppitunti 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — kysyä</span></button><p class=\"lesson1-training-hint\">Napauta korttia nähdäksesi imperatiivimuodot.</p></div></div></details>"
};

